import React, { useState, useEffect, useRef } from 'react';
import Blobs from '../components/Blobs';
import Orb3D from '../components/Orb3D';

const PHASES = [
  { name:'Andas in',  seconds:4, variant:'slate', label:'Djupt in genom näsan' },
  { name:'Håll',      seconds:7, variant:'dark',  label:'Håll stilla' },
  { name:'Andas ut',  seconds:8, variant:'moss',  label:'Sakta ut genom munnen' },
];
const TOTAL = 4;

export default function Breathing({ setPage }) {
  const [running, setRunning] = useState(false);
  const [done,    setDone]    = useState(false);
  const [phase,   setPhase]   = useState(0);
  const [count,   setCount]   = useState(0);
  const [cycle,   setCycle]   = useState(0);
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    setPhase(pi); setCycle(ci); setCount(PHASES[pi].seconds);
    let c = PHASES[pi].seconds;
    timer.current = setInterval(()=>{
      c--; setCount(c);
      if (c <= 0) {
        clearInterval(timer.current);
        const np = (pi+1) % PHASES.length;
        setTimeout(()=>runPhase(np, np===0 ? ci+1 : ci), 400);
      }
    }, 1000);
  };

  const start = () => { setRunning(true); setDone(false); runPhase(0,0); };
  useEffect(()=>()=>clearInterval(timer.current), []);

  const cur = PHASES[phase];

  if (done) return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant="calm" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'0 32px', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:28 }}>
          <Orb3D size={240} variant="moss" speed={0.2} />
        </div>
        <h2 style={{ fontSize:'clamp(32px,7vw,52px)', fontWeight:700, letterSpacing:'-0.04em', color:'#1a1a1e', marginBottom:14 }}>Bra jobbat</h2>
        <p style={{ fontSize:15, color:'rgba(26,26,30,0.45)', marginBottom:40, fontWeight:300 }}>4 omgångar klara. Ditt nervsystem har lugnat ner sig.</p>
        <div style={{ display:'flex', gap:10, justifyContent:'center', flexWrap:'wrap' }}>
          <button onClick={()=>setPage('checkin')} style={{ padding:'12px 24px', borderRadius:100, background:'#1a1a1e', color:'#fff', fontSize:13, fontWeight:600 }}>Checka in humöret</button>
          <button onClick={()=>{setDone(false);setRunning(false);}} className="glass" style={{ padding:'12px 24px', borderRadius:100, color:'rgba(26,26,30,0.6)', fontSize:13 }}>Igen</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', position:'relative' }}>
      <Blobs variant="calm" />
      <div style={{ position:'relative', zIndex:1, padding:'80px 28px 52px', maxWidth:480, margin:'0 auto', display:'flex', flexDirection:'column', alignItems:'center' }}>

        {/* Phase labels — top */}
        <div style={{ width:'100%', marginBottom:32, animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(26,26,30,0.35)', marginBottom:12 }}>Andningsövning</p>
          <div style={{ display:'flex', gap:20 }}>
            {PHASES.map((p,i)=>(
              <div key={i}>
                <div style={{ fontSize:22, fontWeight:700, color: running&&phase===i ? '#1a1a1e' : 'rgba(26,26,30,0.2)', lineHeight:1, marginBottom:3, transition:'color .4s' }}>{p.seconds}</div>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, color: running&&phase===i ? 'rgba(26,26,30,0.5)' : 'rgba(26,26,30,0.18)', letterSpacing:'0.1em', textTransform:'uppercase', transition:'color .4s' }}>{p.name}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Orb — expands/contracts with breathing */}
        <div style={{ marginBottom:36, position:'relative' }}>
          <div style={{
            transition: running
              ? phase===0 ? `transform ${PHASES[0].seconds * 0.85}s cubic-bezier(0.4,0,0.2,1)`
              : phase===1 ? 'transform 0.5s ease'
              : `transform ${PHASES[2].seconds * 0.85}s cubic-bezier(0.4,0,0.6,1)`
              : 'transform 1s ease',
            transform: running
              ? phase===0 ? 'scale(1.22)' : phase===1 ? 'scale(1.22)' : 'scale(0.82)'
              : 'scale(1)',
          }}>
            <Orb3D size={300} variant={running ? cur.variant : 'dark'} speed={running ? (phase===1 ? 0.05 : 0.35) : 0.25} />
          </div>

          {/* Count overlay */}
          {running && (
            <div style={{ position:'absolute', inset:0, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', pointerEvents:'none' }}>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(255,255,255,0.5)', marginBottom:4 }}>{cur.name}</div>
              <div style={{ fontSize:56, fontWeight:700, color:'rgba(255,255,255,0.9)', lineHeight:1 }}>{count}</div>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.35)', marginTop:6 }}>{cycle+1} / {TOTAL}</div>
            </div>
          )}
        </div>

        {/* Bottom */}
        {running ? (
          <div className="glass" style={{ borderRadius:16, padding:'14px 18px', width:'100%', textAlign:'center' }}>
            <p style={{ fontSize:14, color:'rgba(26,26,30,0.6)', fontWeight:300 }}>{cur.label}</p>
          </div>
        ) : (
          <div style={{ width:'100%', animation:'fadeUp .7s .15s cubic-bezier(0.16,1,0.3,1) both' }}>
            <h1 style={{ fontSize:'clamp(36px,8vw,56px)', fontWeight:700, letterSpacing:'-0.05em', lineHeight:0.88, color:'#1a1a1e', marginBottom:12 }}>4–7–8</h1>
            <p style={{ fontSize:14, color:'rgba(26,26,30,0.45)', fontWeight:300, lineHeight:1.7, marginBottom:28, maxWidth:300 }}>Aktiverar det parasympatiska nervsystemet och minskar stressnivåer.</p>
            <button onClick={start} style={{ width:'100%', padding:'15px', borderRadius:100, background:'#1a1a1e', color:'#fff', fontSize:14, fontWeight:600 }}>Starta</button>
          </div>
        )}
      </div>
    </div>
  );
}
